import {renewDemoTasks} from './demo.mjs';
import {TYPES,STATUS,createState,publish,transition,credit,selectTasks,restore,migrate,message} from './model.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 5h12M8 12h12M8 19h12M3 5h.01M3 12h.01M3 19h.01',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',bell:'M18 8a6 6 0 00-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',search:'M10.5 3a7.5 7.5 0 110 15 7.5 7.5 0 010-15 M16 16l5 5',box:'M3 7l9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5M12 12v10M7 4.8l10 5.5',coffee:'M4 8h12v8a4 4 0 01-4 4H8a4 4 0 01-4-4z M16 8h2a3 3 0 010 6h-2M7 2v3M12 2v3',print:'M6 9V3h12v6M6 18H3v-8h18v8h-3M6 14h12v7H6z M17 12h1',leaf:'M20 3C7 2 2 7 5 15c5 8 16 4 15-12zM4 21L16 8',star:'M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z',close:'M6 6l12 12M6 18L18 6',arrow:'M4 12h15M13 6l6 6-6 6',check:'M5 12l4 4L19 6',clock:'M12 3a9 9 0 110 18 9 9 0 010-18M12 7v5l3 2',chat:'M4 4h16v12H9l-5 4z',pin:'M12 21s7-7 7-12a7 7 0 00-14 0c0 5 7 12 7 12z M12 6a3 3 0 110 6 3 3 0 010-6'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const typeIcon=t=>icon({'快递代取':'box','好物代买':'coffee','打印跑腿':'print','校园互助':'leaf'}[t]);
const typeClass=t=>({'快递代取':'parcel','好物代买':'buy','打印跑腿':'print','校园互助':'help'}[t]);
const KEY='campus-dabashou-v2';let state,storageUnavailable=false;
try{const raw=localStorage.getItem(KEY);state=raw?restore(raw):migrate(localStorage.getItem('campus-tasks-v1'))}catch{state=createState();storageUnavailable=true}
let view=['hall','mine','credit','messages','about'].includes(location.hash.slice(1))?location.hash.slice(1):'hall',mineTab='all',filters={query:'',type:'全部',area:'全部校区',sort:'latest',favorites:false},activeTask=null,toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageUnavailable=false}catch{storageUnavailable=true;toast('浏览器未允许保存；本次操作仅保留到页面关闭。')}}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200)}
const time=v=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const remaining=t=>{const m=Math.ceil((t.deadline-Date.now())/60000);return m<=0?'已超时':m<60?`${m} 分钟内`:m<1440?`${Math.ceil(m/60)} 小时内`:'今天内'};
const isMine=t=>t.owner==='me'||t.runner==='me';
const empty=(title,text,button='去任务大厅看看',action='navigate',v='hall')=>`<div class="empty"><div class="empty-icon">${icon('leaf')}</div><h3>${title}</h3><p>${text}</p><button class="secondary small" data-action="${action}" data-view="${v}">${button}</button></div>`;
function nav(){const unread=state.messages.filter(m=>!m.read).length;$('#navigation').innerHTML=[['hall','grid','任务大厅'],['mine','list','我的任务'],['credit','shield','信用中心'],['messages','chat','消息中心']].map(([id,i,n])=>`<button class="nav-item ${view===id?'active':''}" data-action="navigate" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${n}</span>${id==='mine'?`<span class="badge">${state.tasks.filter(t=>isMine(t)&&['accepted','delivered','completed'].includes(t.status)).length}</span>`:id==='messages'&&unread?`<span class="badge">${unread}</span>`:''}</button>`).join('');$('#page-name').textContent={hall:'任务大厅',mine:'我的任务',credit:'信用中心',messages:'消息中心',about:'产品说明'}[view];$('#notification').innerHTML=icon('bell')+(unread?'<span class="notification-dot"></span>':'')}
const artwork=`<div class="campus-scene" aria-hidden="true"><div class="scene-sticker"><span class="sticker-dot"></span> 校园里的每一站，都有温暖</div><img src="./campus-scene.svg" width="560" height="380" alt=""><div class="scene-label label-library">图书馆</div><div class="scene-label label-dorm">学生宿舍</div><div class="route-ticket"><span class="ticket-icon">${icon('box')}</span><span><b>刚好顺路，一起搭把手</b><small>取件 · 代买 · 打印 · 校园互助</small></span><span class="ticket-check">${icon('check')}</span></div><span class="scene-caption">校园路线示意</span></div>`;
function card(t){return `<article class="card"><div class="card-head"><span class="type-icon ${typeClass(t.type)}">${typeIcon(t.type)}</span><span class="type-label">${t.type}</span><div class="reward">${t.price===0?'互助':`<em>¥</em>${t.price}`}<small>${t.price===0?'一份感谢':'感谢金'}</small></div><button class="save-button ${state.favorites.includes(t.id)?'saved':''}" data-action="favorite" data-id="${esc(t.id)}" aria-label="${state.favorites.includes(t.id)?'取消收藏':'收藏'}任务" aria-pressed="${state.favorites.includes(t.id)}">${icon('star')}</button></div><button class="card-title" data-action="detail" data-id="${esc(t.id)}" title="${esc(t.title)}">${esc(t.title)}</button><div class="route"><span><i class="point"></i>${esc(t.from)}</span><span><i class="point end"></i>${esc(t.to)}</span></div><div class="task-meta"><span class="tag ${t.deadline-Date.now()<1900000?'urgent':''}">${remaining(t)}</span><span class="tag">${esc(t.area)}</span>${t.owner==='me'?'<span class="tag">我发布的</span>':''}</div><div class="card-foot"><span class="avatar">${esc(t.name[0])}</span><span class="person">${esc(t.name)} <small>信用 ${t.ownerCredit}</small></span><button data-action="detail" data-id="${esc(t.id)}">${t.owner==='me'?'管理任务':t.deadline<=Date.now()?'查看任务':'我来帮忙'}</button></div></article>`}
function hall(){return `<section class="hero"><div class="hero-text"><div class="hero-intro"><span></span> 校园里的事，顺路就好</div><h1>你的顺路，<br>刚好是我的需要。</h1><p>取个快递，带杯咖啡，帮一个小忙。<br>让校园生活轻松一点，让彼此的距离近一点。</p><div class="hero-actions"><button class="primary" data-action="publish">发布一个小任务 ${icon('arrow')}</button><button class="hero-secondary" data-action="guide">第一次来？看看怎么玩 ${icon('arrow')}</button></div><div class="hero-footnote"><span class="mini-avatars"><i>林</i><i>陈</i><i>周</i></span><span>从一句「我来帮你」开始 <small>示例校园，随时体验</small></span></div></div>${artwork}</section><div class="hall-layout"><section class="task-section"><div class="section-title"><div><h2>发现一份顺路的小事</h2><small id="result-count"></small></div><button class="credit-pill" data-action="navigate" data-view="credit">${icon('shield')}<span>我的信用 <b>${credit(state)}</b></span>${icon('arrow')}</button></div><div class="discovery-tools"><label class="search">${icon('search')}<input id="search" aria-label="搜索任务或地点" placeholder="想找什么？试试「快递」或「图书馆」" value="${esc(filters.query)}" maxlength="80"></label><div class="filter-selects"><select id="area" aria-label="校区筛选">${['全部校区','北校区','中心区','南校区'].map(a=>`<option ${filters.area===a?'selected':''}>${a}</option>`).join('')}</select><select id="sort" aria-label="任务排序">${[['latest','最新发布'],['deadline','时限优先'],['price','酬谢优先']].map(([v,n])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="filter-row"><div class="chips">${['全部',...TYPES].map(t=>`<button class="chip ${filters.type===t?'active':''}" data-action="category" data-type="${t}" aria-pressed="${filters.type===t}">${t==='全部'?icon('grid'):typeIcon(t)}<span>${t==='全部'?'全部任务':t}</span></button>`).join('')}</div><label class="checkbox"><input type="checkbox" id="favorites" ${filters.favorites?'checked':''}>只看收藏</label></div>${state.tasks.some(t=>/^seed-[0-5]$/.test(t.id)&&t.owner!=='me'&&!t.runner&&t.status==='open'&&t.deadline<=Date.now())?'<div class="sample-refresh"><span>上次访问的示例任务已超时，刷新后可继续体验。</span><button data-action="renew-demo">刷新示例时限</button></div>':''}<div class="cards" id="task-list"></div></section></div><section class="community-strip"><div class="community-symbol">${icon('leaf')}</div><div><h3>小忙认真帮，信任慢慢长。</h3><p>按时完成，确认交接，每一份帮助都留下记录。</p></div><button class="text-button" data-action="navigate" data-view="credit">了解校园信用 ${icon('arrow')}</button></section><div class="welcome-strip"><span>${icon('shield')} 不替考、不违规占座。保护隐私，在公共地点放心交接。</span><button class="text-button" data-action="about">了解互助约定</button></div>`}
function renderCards(){if(!$('#task-list'))return;const list=selectTasks(state,filters);$('#result-count').textContent=`${list.length} 个任务 · 演示数据`;$('#task-list').innerHTML=list.length?list.map(card).join(''):empty('暂时没有匹配的任务','换一个关键词或校区试试，也可以发布你的需要。','清除筛选','clear')}
function mine(){const all=state.tasks.filter(isMine),counts=[all.length,all.filter(t=>['accepted','delivered'].includes(t.status)).length,all.filter(t=>['completed','reviewed'].includes(t.status)).length,all.filter(t=>t.owner==='me').length];let list=all.filter(t=>mineTab==='all'||mineTab==='posted'&&t.owner==='me'||mineTab==='taken'&&t.runner==='me'||mineTab==='finished'&&['completed','reviewed'].includes(t.status));return `<div class="page-heading"><h1>我的任务</h1><p>从一声「我来帮忙」，到一声「谢谢你」。每一步都有记录。</p></div><div class="summary-grid">${['参与任务','正在进行','已确认完成','我发布的'].map((x,i)=>`<div class="stat"><small>${x}</small><strong>${counts[i]}</strong></div>`).join('')}</div><div class="tabline">${[['all','全部任务'],['taken','我接的单'],['posted','我发布的'],['finished','已完成']].map(([id,n])=>`<button class="${mineTab===id?'active':''}" data-action="mine-tab" data-tab="${id}">${n}</button>`).join('')}</div>${list.length?list.map(t=>`<article class="my-row"><span class="type-icon ${typeClass(t.type)}">${typeIcon(t.type)}</span><div class="grow"><h3>${esc(t.title)}</h3><p>${esc(t.from)} → ${esc(t.to)}</p><p>${t.owner==='me'?'我发布的':'我接的单'} · ${time(t.created)}</p></div><span class="tag status">${STATUS[t.status]}</span><b class="muted">¥${t.price}</b><button class="soft" data-action="detail" data-id="${esc(t.id)}">查看进度 →</button></article>`).join(''):empty('还没有这样的任务','发布一个需求，或去大厅接下你的第一单。')}`}
function creditPage(){const c=credit(state),completed=state.tasks.filter(t=>t.runner==='me'&&['completed','reviewed'].includes(t.status)).length;return `<div class="page-heading"><h1>让每一份善意，都有回响</h1><p>信用不是一句承诺，而是每一次认真完成的小事。</p></div><div class="credit-layout"><section class="credit-hero"><h3>我的校园信用 <span class="tag">演示账户</span></h3><div class="score-circle"><b>${c}</b><span>${c>=90?'守约达人':'值得信赖'} / 100</span></div><p>已确认完成 ${completed} 单 · 初始信用 80 分</p><div class="badges"><span class="tag">🌱 校园新伙伴</span>${completed?'<span class="tag">✦ 第一份善意</span>':''}${c>=90?'<span class="tag">◇ 守约达人</span>':''}</div></section><section class="info-panel"><h3>信用怎么积累？</h3><div class="rule"><div><b>完成任务，获得发布者确认</b><p>送达不直接加分，确认交接后计入。</p></div><strong class="points">+3</strong></div><div class="rule"><div><b>收到 4～5 星评价</b><p>每单仅记一次，好评是额外的认可。</p></div><strong class="points">+2</strong></div><div class="rule"><div><b>信用上限为 100 分</b><p>明细持续保留，重复操作不会重复加分。</p></div>${icon('shield')}</div><div class="notice green" style="margin-top:15px">信用仅为本地演示值，不代表真实校内身份或担保。实名校验、申诉仲裁是正式上线阶段的扩展方向。</div></section></div><section class="info-panel ledger"><h3>信用成长记录</h3>${state.ledger.length?state.ledger.map(e=>`<div class="ledger-row"><span>${esc(e.text)}<small>${time(e.time)}</small></span><strong>+${e.points}</strong></div>`).join(''):'<p class="muted" style="font-size:12px">还没有新的履约记录。接一单顺路任务，开始你的信用成长吧。</p>'}<div class="ledger-row"><span>加入搭把手 · 初始信用<small>每个演示账户从相同起点开始</small></span><strong>80</strong></div></section>`}
function messages(){return `<div class="section-title page-heading"><div><h1>消息中心</h1><p>发布、接单、确认完成，重要进展都在这里。</p></div><button class="secondary small" data-action="read-all">全部标为已读</button></div>${state.messages.map(m=>`<article class="message ${m.read?'':'unread'}"><span class="type-icon help">${icon(m.taskId?'box':'bell')}</span><div class="grow"><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><small>${time(m.time)} · 本地系统通知</small></div>${m.taskId?`<button class="soft" data-action="open-message" data-id="${esc(m.id)}">查看</button>`:''}</article>`).join('')}`}
function about(){return `<div class="page-heading"><h1>不是跑得更快，而是离彼此更近</h1><p>搭把手 · 校园跑腿互助平台 / 产品原型 v3.0</p></div><section class="about-banner"><h2>把校园里的「顺路」连接起来。</h2><p>为需要帮助的同学找到可信伙伴，也让愿意帮助的同学积累可见的信用。</p></section><div class="about-grid"><section class="info-panel"><h3>我们关注的三个小难题</h3><ul><li>群消息容易被刷走 → 分类、地点搜索和时限排序。</li><li>不认识对方，缺少信任 → 信用信息、履约时间线和评价记录。</li><li>接单后进度不清晰 → 接单、送达、发布者确认和评价分步推进。</li></ul></section><section class="info-panel"><h3>一分钟体验完整流程</h3><ol style="padding-left:18px"><li>在大厅选择一个任务，点击「确认接单」。</li><li>标记送达，再使用「模拟发布者确认」。</li><li>模拟发布者评价，在信用中心查看积分。</li><li>也可以自己发布任务，体验发布者视角。</li></ol></section><section class="info-panel"><h3>真实能力与演示边界</h3><p>当前支持任务发布、筛选、收藏、状态流转、评价、信用明细与本地通知。数据保存在浏览器，不与其他访客共享。学校、学生、任务均为示例；不收集学号、手机号、取件码，也不发起真实支付。</p></section><section class="info-panel"><h3>正式产品的下一步</h3><p>接入校内身份认证和服务端数据库，实现多用户协作；按校规引入费用托管、纠纷申诉和信用治理。身份与联系信息最小化展示，关键操作保留审计记录。</p></section></div><section class="info-panel" style="margin-top:20px"><h3>演示空间管理</h3><p class="muted" style="font-size:12px">重置只影响当前浏览器里的演示数据，其他访客不受影响。旧版发布的任务会在首次升级时保留。</p><button class="secondary small" style="margin-top:15px" data-action="reset-ask">重置演示数据</button></section>`}
function render(){nav();$('#content').innerHTML=(view==='hall'?hall():view==='mine'?mine():view==='credit'?creditPage():view==='messages'?messages():about())+(storageUnavailable?'<div class="notice" style="margin-top:16px">浏览器存储未启用，本次操作仅在当前页面保留。</div>':'');if(view==='hall')renderCards()}
function navigate(v){view=v;location.hash=v;render();window.scrollTo({top:0,behavior:'instant'})}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function publishModal(){activeTask=null;modal('发布一个小任务',`<p style="margin-top:0;margin-bottom:18px">把需要说清楚，让顺路的同学更好帮你。</p><form id="publish-form"><div class="form-grid"><label class="field full">任务标题 *<input name="title" required maxlength="50" placeholder="例如：帮取一个北门快递，送到 8 号楼"></label><label class="field">任务类型<select name="type">${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">所在校区<select name="area"><option>北校区</option><option>中心区</option><option>南校区</option></select></label><label class="field">出发 / 取件地点 *<input name="from" required maxlength="40" placeholder="例如：北门菜鸟驿站"></label><label class="field">送达地点 *<input name="to" required maxlength="40" placeholder="例如：8 号宿舍楼下"></label><label class="field">感谢金（元） *<input name="price" required type="number" min="0" max="200" step="0.5" value="3"><small>仅跑腿酬谢，商品费另计。0 元表示无偿互助。</small></label><label class="field">希望多久内完成<select name="minutes"><option value="30">30 分钟内</option><option value="60" selected>1 小时内</option><option value="120">2 小时内</option><option value="360">6 小时内</option><option value="1440">24 小时内</option></select></label><label class="field full">补充说明<textarea name="description" maxlength="300" placeholder="物品大小、交接方式、特殊要求……请勿填写手机号、学号或取件码。"></textarea></label></div><div class="notice" style="margin-top:16px">这是演示发布，不产生真实订单或付款。请勿发布替考、违规占座或违禁品相关需求。</div><div class="form-error" id="form-error" role="alert"></div><div class="actions"><button class="secondary" type="button" data-action="close">再想想</button><button class="primary" type="submit">确认发布 →</button></div></form>`)}
function detail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;activeTask=id;const owner=t.owner==='me',runner=t.runner==='me';let action='';if(t.status==='open'){action=owner?`<button class="secondary danger" data-action="cancel-ask" data-id="${esc(id)}">撤销任务</button><button class="primary" data-action="demo-accept" data-id="${esc(id)}" ${t.deadline<=Date.now()?'disabled':''}>模拟同学接单</button>`:`<button class="primary" data-action="accept-ask" data-id="${esc(id)}" ${t.deadline<=Date.now()?'disabled':''}>${t.deadline<=Date.now()?'任务已超时':'确认接单 →'}</button>`}else if(t.status==='accepted'){action=`<button class="primary" data-action="${runner?'deliver':'demo-deliver'}" data-id="${esc(id)}">${runner?'我已送达':'模拟接单人送达'}</button>`}else if(t.status==='delivered'){action=`<button class="primary" data-action="confirm" data-id="${esc(id)}">${owner?'确认收到，完成任务':'模拟发布者确认'}</button>`}else if(t.status==='completed'){action=`<button class="primary" data-action="review" data-id="${esc(id)}">${owner?'评价这次帮助':'模拟发布者评价'}</button>`}
 modal('任务详情',`<div class="detail-heading"><span class="type-icon ${typeClass(t.type)}">${typeIcon(t.type)}</span><div style="flex:1"><h3>${esc(t.title)}</h3><small>${t.type} · ${esc(t.name)} · 信用 ${t.ownerCredit}（示例）</small></div><div class="reward"><em>¥</em>${t.price}<small>感谢金</small></div></div><div class="detail-route"><div class="route"><span><i class="point"></i>从 ${esc(t.from)}</span><span><i class="point end"></i>到 ${esc(t.to)}</span></div></div><div class="detail-meta"><span class="tag status">${STATUS[t.status]}</span><span class="tag">${esc(t.area)}</span><span class="tag">期望 ${time(t.deadline)} 前送达</span></div><p class="detail-description">${esc(t.description||'发布者暂无补充说明，请先沟通确认再行动。')}</p><div class="notice green" style="margin-top:15px">公开页面不展示取件码或真实联系方式。正式产品中仅向接单双方开放必要的交接信息。</div>${t.rating?`<div class="detail-section"><h3>本次评价</h3><div class="rating-stars" aria-label="${t.rating}星">${'★'.repeat(t.rating)}${'☆'.repeat(5-t.rating)}</div><p class="detail-description">${esc(t.comment||'谢谢你的帮助！')}</p></div>`:''}<div class="detail-section"><h3>履约进度</h3><ol class="timeline">${t.history.map(h=>`<li>${esc(h.text)}<small>${time(h.time)}</small></li>`).join('')}</ol></div>${isMine(t)?`<div class="detail-section"><h3>我的交接备忘</h3><p class="muted" style="font-size:10px">仅本机可见，不会发送给其他用户。请勿填写敏感信息。</p>${state.notes.filter(n=>n.taskId===id).map(n=>`<div class="note-item">${esc(n.text)}<small style="display:block">${time(n.time)}</small></div>`).join('')}<form id="note-form" class="note-form"><input name="note" aria-label="交接备忘" placeholder="例如：到楼下后再确认交接" maxlength="200" required><button class="soft">保存</button></form></div>`:''}${action?`<div class="notice" style="margin-top:18px">演示模式：带「模拟」的按钮用于体验另一方操作，不代表真实用户确认。完成后可在信用中心查看积分。</div><div class="actions">${action}</div>`:''}`)}
function review(id){activeTask=id;modal('给这次帮助一个评价',`<form id="review-form"><p class="muted" style="font-size:12px;margin-bottom:18px">${state.tasks.find(t=>t.id===id).owner==='me'?'你正在以发布者身份评价。':'正在模拟发布者视角。'}每单只能评价一次。</p><label class="field">满意度<select name="rating"><option value="5">★★★★★ 非常满意</option><option value="4">★★★★☆ 满意</option><option value="3">★★★☆☆ 一般</option><option value="2">★★☆☆☆ 有待改善</option><option value="1">★☆☆☆☆ 不满意</option></select></label><label class="field" style="margin-top:15px">想说的话<textarea name="comment" maxlength="200" placeholder="具体的感谢，是最好的鼓励。"></textarea></label><div class="form-error" id="form-error" role="alert"></div><div class="actions"><button type="button" class="secondary" data-action="detail" data-id="${esc(id)}">返回</button><button class="primary">提交评价</button></div></form>`)}
function mutate(id,action,actor,data){try{transition(state,id,action,actor,data);persist();render();detail(id);toast({accept:'接单成功，可以在「我的任务」查看',deliver:'已标记送达，等待发布者确认',confirm:'已确认完成，履约记录已更新',review:'评价已保存，信用记录已更新',cancel:'任务已撤销'}[action])}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,t=state.tasks.find(t=>t.id===id);
 if(a==='renew-demo'){const count=renewDemoTasks(state);persist();render();toast(count+' 个示例时限已刷新，你的任务与履约记录保持不变')}else if(a==='navigate'){navigate(b.dataset.view)}else if(a==='about'){navigate('about')}else if(a==='close'){$('#modal').close()}else if(a==='publish'){publishModal()}else if(a==='detail'){detail(id)}else if(a==='category'){filters.type=b.dataset.type;render()}else if(a==='clear'){filters={query:'',type:'全部',area:'全部校区',sort:'latest',favorites:false};render()}else if(a==='mine-tab'){mineTab=b.dataset.tab;render()}else if(a==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();renderCards()}else if(a==='read-all'){state.messages.forEach(m=>m.read=true);persist();render();toast('全部消息已标记为已读')}else if(a==='open-message'){const m=state.messages.find(m=>m.id===id);m.read=true;persist();render();detail(m.taskId)}else if(a==='accept-ask'){modal('确认接下这个小任务？',`<h3>${esc(t.title)}</h3><p>路线：${esc(t.from)} → ${esc(t.to)}</p><p>请在 ${time(t.deadline)} 前送达。感谢金 ¥${t.price}（演示）。</p><div class="notice">请确认路线和时间适合自己。接单后需要标记送达，再由发布者确认。</div><div class="actions"><button class="secondary" data-action="detail" data-id="${esc(id)}">再看看</button><button class="primary" data-action="accept" data-id="${esc(id)}">确认接单</button></div>`)}else if(a==='accept'){mutate(id,'accept','me')}else if(a==='demo-accept'){mutate(id,'accept','demo-runner')}else if(a==='deliver'){mutate(id,'deliver','me')}else if(a==='demo-deliver'){mutate(id,'deliver',t.runner)}else if(a==='confirm'){mutate(id,'confirm',t.owner)}else if(a==='review'){review(id)}else if(a==='cancel-ask'){modal('撤销这个任务？',`<p>任务尚未被接单，撤销后会从大厅移除，仍可在「我的任务」查看记录。</p><div class="actions"><button class="secondary" data-action="detail" data-id="${esc(id)}">保留任务</button><button class="primary" data-action="cancel" data-id="${esc(id)}">确认撤销</button></div>`)}else if(a==='cancel'){mutate(id,'cancel','me')}else if(a==='guide'){modal('一分钟，体验一次校园互助',`<ol class="steps"><li><span class="number">1</span><div><b>先去大厅接一个任务</b><p>选择「我来帮忙」，阅读详情并确认。</p></div></li><li><span class="number">2</span><div><b>模拟走完履约流程</b><p>点击「我已送达」→「模拟发布者确认」→「模拟发布者评价」。</p></div></li><li><span class="number">3</span><div><b>去信用中心看看</b><p>确认完成 +3 分，4～5 星好评再 +2 分。</p></div></li></ol><div class="notice" style="margin-top:20px">所有操作均为本机演示，不会向真实学生发单，不发生真实交易。</div><div class="actions"><button class="primary" data-action="close">开始体验 →</button></div>`)}else if(a==='reset-ask'){modal('重新开始体验？',`<p>将清除当前浏览器的任务、收藏、评价、备忘与信用记录，并恢复 6 条新示例任务。此操作不可撤销。</p><div class="actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="reset">确认重置</button></div>`)}else if(a==='reset'){state=createState();persist();$('#modal').close();navigate('hall');toast('演示空间已重置，可以重新体验了')}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.query=e.target.value;renderCards()}});
document.addEventListener('change',e=>{if(e.target.id==='area')filters.area=e.target.value;else if(e.target.id==='sort')filters.sort=e.target.value;else if(e.target.id==='favorites')filters.favorites=e.target.checked;else return;renderCards()});
document.addEventListener('submit',e=>{if(!['publish-form','review-form','note-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{if(e.target.id==='publish-form'){const t=publish(state,data);persist();view='mine';mineTab='posted';location.hash='mine';render();detail(t.id);toast('发布成功！可以模拟同学接单，体验发布者视角。')}else if(e.target.id==='review-form'){const t=state.tasks.find(t=>t.id===activeTask);transition(state,t.id,'review',t.owner,data);persist();render();detail(t.id);toast('评价成功，信用记录已更新')}else{const text=data.note.trim();if(!text)return;state.notes.push({id:crypto.randomUUID(),taskId:activeTask,text:text.slice(0,200),time:Date.now()});persist();detail(activeTask);toast('备忘已保存，仅本机可见')}}catch(err){const box=$('#form-error');if(box)box.textContent=err.message;else toast(err.message)}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['hall','mine','credit','messages','about'].includes(v)&&v!==view){view=v;render()}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){state=restore(e.newValue);render();if($('#modal').open){$('#modal').close();toast('另一标签页更新了任务，请重新打开查看')}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
persist();render();setInterval(()=>{if(view==='hall'&&!$('#modal').open)renderCards()},60000);

